import {migrateAtas,atasForProduct} from './ata-logic.js';
import {registrationEditor as edit} from './registrations.js';
import {requestEditor,requestSummary,receiptEditor,waitingPanel} from './requests.js';
import {migrateRequests,remaining,requestGroups} from './request-logic.js';
import {Store,statuses} from './store.js';import {icon,hydrate} from './icons.js';import {escape as esc,normalize,statusClass,number,toast,filtered} from './utils.js';import {FileIO} from './fileio.js';import {confirmDelete,importModal,importPreview,open,close} from './modals.js';
migrateRequests(Store.data);
if(!Store.data.ataRelationsVersion){migrateAtas(Store.data);Store.save()}
if(!Store.data.requestFlowVersion){Store.data.columns=[...new Set([...Store.data.columns,'received','remaining','responsible','ramal','ata','requestNumber'])];Store.data.requestFlowVersion=2;Store.save()}
const routes={dashboard:['Visão geral','grid'],requests:['Solicitações','clipboard'],products:['Produtos','box'],sectors:['Setores','building'],atas:['Atas de registro','file'],reports:['Relatórios','chart']};let route='dashboard',filters={search:'',sector:'',status:'',code:''},sort={key:'date',direction:-1},page=1,pageSize=6,selected=new Set(),chartPeriod='6';const main=document.getElementById('main');
const titles={code:'Código',product:'Produto',unit:'Unidade',quantity:'Qtd.',sector:'Setor',status:'Status',date:'Data',ata:'ATA',name:'Setor',responsible:'Responsável',contact:'Contato',number:'Número da ATA',supplier:'Fornecedor',validity:'Vigência até',description:'Descrição',received:'Recebido',remaining:'Pendente',ramal:'Ramal',requestNumber:'Solicitação',ataNames:'ATAs vinculadas',sectorNames:'Setores participantes',productNames:'Produtos vinculados'};
const activeType=()=>route==='dashboard'||route==='reports'?'requests':route;const getRows=()=>{const type=activeType();let rows=Store.data[type];if(type==='products')rows=rows.map(r=>({...r,ataNames:atasForProduct(Store.data,r.id).map(a=>a.number).join(', ')})).filter(r=>!filters.ataId||Store.data.atas.find(a=>a.id===filters.ataId)?.productIds?.includes(r.id));if(type==='atas')rows=rows.map(r=>({...r,sectorNames:Store.data.sectors.filter(s=>r.sectorIds?.includes(s.id)).map(s=>s.name).join(', '),productNames:Store.data.products.filter(p=>r.productIds?.includes(p.id)).map(p=>p.product).join(', ')}));return filtered(rows,filters,sort)};const button=(id,label,ic,primary=false)=>`<button id="${id}" class="btn ${primary?'primary':''}" data-testid="${id}">${icon(ic)}${label}</button>`;
function navigation(){document.getElementById('navigation').innerHTML=Object.entries(routes).map(([key,[label,ic]],i)=>`${i===5?'<div class="nav-separator"></div><div class="nav-label">ANÁLISE</div>':''}<a href="#${key}" class="${route===key?'active':''}" title="${label}" data-testid="nav-${key}">${icon(ic)}${label}${key==='requests'?`<span class="nav-count">${requestGroups(Store.data.requests).length}</span>`:''}</a>`).join('');document.getElementById('breadcrumb').textContent=routes[route][0]}
function heading(){const labels={dashboard:['Visão geral','Acompanhe e organize as solicitações de materiais em um só lugar.'],requests:['Solicitações','Gerencie os pedidos de materiais e acompanhe cada etapa.'],products:['Catálogo de produtos','Todos os materiais disponíveis para as solicitações dos setores.'],sectors:['Setores','Conecte setores, responsáveis e contatos da sua secretaria.'],atas:['Atas de registro de preços','Organize fornecedores e a vigência dos registros de preços.'],reports:['Relatórios','Transforme os dados das solicitações em decisões mais claras.']};const [title,desc]=labels[route];return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${route==='reports'?button('print','Imprimir relatório','printer'):button('import','Importar planilha','upload')}${route==='dashboard'||route==='requests'?button('new','Nova solicitação','plus',true):route==='reports'?button('export','Exportar dados','download',true):button('new',route==='products'?'Novo produto':route==='sectors'?'Novo setor':'Nova ATA','plus',true)}</div></div>`}
function stats(){const data=requestGroups(Store.data.requests);const cards=[['Total de solicitações',data.length,'clipboard','purple','Todos os pedidos registrados'],['Pendentes',data.filter(r=>r.status==='Pendente').length,'clock','orange','Aguardando atendimento'],['Em andamento',data.filter(r=>r.status==='Em andamento').length,'refresh','blue','Em processo de atendimento'],['Concluídas',data.filter(r=>r.status==='Concluída').length,'check','green','Materiais entregues aos setores']];return `<section class="stats" aria-label="Indicadores de solicitações">${cards.map(([label,value,ic,color,foot])=>`<article class="stat"><div class="stat-top">${label}<span class="stat-icon ${color}">${icon(ic)}</span></div><div class="stat-value" data-testid="stat-${normalize(label).replaceAll(' ','-')}">${number(value)}</div><div class="stat-foot">${color==='green'?'<span class="positive">✓</span>':''}${foot}</div></article>`).join('')}</section>`}
function charts(){const rows=requestGroups(Store.data.requests),colors=['#e9ba64','#9c80dd','#68b8a0','#d69ca5'];let angle=0;const gradients=statuses.map((s,i)=>{const start=angle;angle+=rows.filter(r=>r.status===s).length/(rows.length||1)*100;return `${colors[i]} ${start}% ${angle}%`}).join(',');const today=new Date();const months=Array.from({length:Number(chartPeriod)},(_,i)=>new Date(today.getFullYear(),today.getMonth()-Number(chartPeriod)+1+i,1));const counts=months.map(date=>{const prefix=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;const rs=rows.filter(r=>r.date?.startsWith(prefix));return {date,total:rs.length,done:rs.filter(r=>r.status==='Concluída').length}});const max=Math.max(4,...counts.map(c=>c.total));return `<section class="middle-grid"><article class="panel"><div class="panel-head"><div><h2>Movimentação de solicitações</h2><p>Uma visão do volume de pedidos ao longo do tempo</p></div><select id="period" class="period" aria-label="Período do gráfico"><option value="6" ${chartPeriod==='6'?'selected':''}>Últimos 6 meses</option><option value="3" ${chartPeriod==='3'?'selected':''}>Últimos 3 meses</option><option value="12" ${chartPeriod==='12'?'selected':''}>Últimos 12 meses</option></select></div><div class="chart-wrap"><div class="axis">${[max,Math.round(max*.75),Math.round(max*.5),Math.round(max*.25),0].map(n=>`<span>${n}</span>`).join('')}</div><div class="chart">${counts.map(c=>`<div class="bar-group" title="${c.date.toLocaleDateString('pt-BR',{month:'long'})}: ${c.total} solicitações, ${c.done} concluídas"><div class="bar" style="height:${c.total/max*95}%"></div><div class="bar secondary" style="height:${c.done/max*95}%"></div><span>${c.date.toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</span></div>`).join('')}</div></div><div class="chart-legend"><span><i class="dot"></i>Solicitações</span><span><i class="dot light"></i>Concluídas</span></div></article><article class="panel"><div class="panel-head"><div><h2>Status das solicitações</h2><p>Distribuição atual dos pedidos</p></div><span class="icon-btn" title="Atualizado a cada alteração">${icon('filter')}</span></div><div class="distribution"><div class="donut" role="img" aria-label="Distribuição dos status das solicitações" style="background:${rows.length?'conic-gradient('+gradients+')':'var(--line)'}"><div class="donut-label"><strong>${rows.length}</strong><small>solicitações</small></div></div><div class="status-legend">${statuses.map((s,i)=>`<div class="legend-row"><i style="background:${colors[i]}"></i>${s}<strong>${rows.filter(r=>r.status===s).length}</strong></div>`).join('')}</div></div></article></section>`}
function table(){const type=activeType(),rows=getRows(),pages=Math.max(1,Math.ceil(rows.length/pageSize));page=Math.min(page,pages);const display=rows.slice((page-1)*pageSize,page*pageSize);const columns=type==='requests'?Store.data.columns:type==='products'?['code','product','unit','ataNames']:type==='sectors'?['name','responsible','contact']:['number','supplier','validity','sectorNames','productNames'];const title=type==='requests'?(route==='dashboard'?'Solicitações recentes':'Todas as solicitações'):type==='products'?'Produtos cadastrados':type==='sectors'?'Setores cadastrados':'Atas cadastradas';return `<section class="panel requests-panel"><div class="panel-head"><div><h2>${title} <span style="color:#a3a6b3;font-size:11px;font-weight:400;margin-left:5px">${Store.data[type].length}</span></h2><p>${type==='requests'?'Cada linha representa um produto. Use ✓ para registrar recebimentos da solicitação.':'Cadastros organizados para simplificar o dia a dia.'}</p></div>${route==='dashboard'?'<a class="subtle-link" href="#requests">Ver todas '+icon('arrow')+'</a>':button('export-table','Exportar','download')}</div><div class="table-toolbar"><div class="filters"><label class="input-wrap">${icon('search')}<input id="search" aria-label="Buscar registros" placeholder="${type==='requests'?'Buscar solicitação...':'Buscar cadastro...'}" value="${esc(filters.search)}" data-testid="global-search"></label>${['requests','products'].includes(type)?`<input id="code-filter" class="filter-select" style="width:108px" placeholder="Código do produto" aria-label="Filtrar por código" value="${esc(filters.code)}" data-testid="code-filter">`:''}${type==='products'?`<select id="ata-filter" class="filter-select" aria-label="Filtrar produtos por ATA"><option value="">Todas as ATAs</option>${Store.data.atas.map(a=>`<option value="${esc(a.id)}" ${filters.ataId===a.id?'selected':''}>${esc(a.number)}</option>`).join('')}</select>`:''}${type==='requests'?`<select id="sector-filter" class="filter-select" aria-label="Filtrar por setor" data-testid="sector-filter"><option value="">Todos os setores</option>${Store.data.sectors.map(s=>`<option ${filters.sector===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}</select><select id="status-filter" class="filter-select" aria-label="Filtrar por status" data-testid="status-filter"><option value="">Todos os status</option>${statuses.map(s=>`<option ${filters.status===s?'selected':''}>${s}</option>`).join('')}</select>`:''}</div><div class="table-extra"><button class="icon-btn" id="reset-filters" title="Limpar filtros" aria-label="Limpar filtros">${icon('refresh')}</button>${route==='dashboard'?`<button id="export-table" class="icon-btn" title="Exportar planilha" aria-label="Exportar planilha">${icon('download')}</button>`:''}<button class="icon-btn" id="print-table" title="Imprimir relatório" aria-label="Imprimir relatório">${icon('printer')}</button></div></div>${selected.size?`<div class="bulk"><strong>${selected.size} selecionado(s)</strong><button class="btn" id="bulk-clone">${icon('copy')}Clonar</button>${type==='requests'?`<select class="filter-select" id="bulk-status"><option value="">Cancelar itens...</option>${statuses.filter(s=>s==='Cancelada').map(s=>`<option>${s}</option>`).join('')}</select>`:''}<button class="btn danger" id="bulk-delete">${icon('trash')}Excluir</button></div>`:''}<div class="table-scroll"><table data-testid="data-grid"><thead><tr><th><input type="checkbox" id="select-all" aria-label="Selecionar todos desta página" ${display.length&&display.every(r=>selected.has(r.id))?'checked':''} data-testid="select-all"></th>${columns.map(key=>`<th draggable="${type==='requests'}" data-key="${key}" aria-sort="${sort.key===key?(sort.direction===1?'ascending':'descending'):'none'}" title="Clique para ordenar${type==='requests'?'; arraste para reordenar':''}">${titles[key]} <span style="opacity:.5;margin-left:6px">${sort.key===key?(sort.direction===1?'↑':'↓'):'↕'}</span></th>`).join('')}<th>Ações</th></tr></thead><tbody>${display.map(r=>`<tr data-testid="data-row"><td><input type="checkbox" data-select="${r.id}" aria-label="Selecionar ${esc(r.product||r.name||r.number)}" ${selected.has(r.id)?'checked':''}></td>${columns.map(k=>`<td>${k==='product'?`<div class="product-cell"><span class="product-icon">${icon(/papel|pasta|bloco|envelope/i.test(r.product)?'file':'box')}</span>${esc(r[k])}</div>`:k==='status'?`<span class="badge ${statusClass(r[k])}">${esc(r[k])}</span>`:k==='code'?`<span class="code">${esc(r[k])}</span>`:k==='quantity'?`<span style="font-weight:600;color:var(--text)">${number(r[k])}</span>`:['ataNames','sectorNames','productNames'].includes(k)?`<span class="link-summary" title="${esc(r[k])}">${esc(r[k]?(r[k].length>130?r[k].slice(0,130)+'…':r[k]):'Sem vínculo')}</span>`:k==='remaining'?`<b>${r.status==='Cancelada'?'—':number(remaining(r))}</b>`:k==='received'?number(r.received||0):k==='validity'?esc(new Date(r[k]+'T12:00:00').toLocaleDateString('pt-BR')):esc(r[k])}</td>`).join('')}<td><div class="row-actions">${type==='requests'?`<button class="icon-btn" data-receive="${esc(r.groupId||r.id)}" title="Ver solicitação e registrar recebimento" aria-label="Ver solicitação e dar baixa" data-testid="row-receive">${icon('check')}</button>`:''}<button class="icon-btn" data-edit="${r.id}" title="Editar" aria-label="Editar ${esc(r.product||r.name||r.number)}" data-testid="edit-record">${icon('edit')}</button><button class="icon-btn" data-clone="${r.id}" title="Clonar" aria-label="Clonar registro" data-testid="clone-record">${icon('copy')}</button><button class="icon-btn" data-delete="${r.id}" title="Excluir" aria-label="Excluir registro" data-testid="delete-record">${icon('trash')}</button></div></td></tr>`).join('')||`<tr><td colspan="${columns.length+2}" class="empty">${Store.data[type].length?'Nenhum resultado para os filtros selecionados.':'Nenhum cadastro ainda. Clique no botão acima para começar.'}</td></tr>`}</tbody></table></div><div class="table-footer"><span>Exibindo ${rows.length?(page-1)*pageSize+1:0}–${Math.min(page*pageSize,rows.length)} de ${rows.length} registros</span><div class="pagination"><select id="page-size" class="period" aria-label="Registros por página">${[6,10,25,50].map(n=>`<option value="${n}" ${pageSize===n?'selected':''}>${n} por página</option>`).join('')}</select><button id="prev" ${page===1?'disabled':''} aria-label="Página anterior">‹</button>${Array.from({length:pages},(_,i)=>i+1).filter(n=>n===1||n===pages||Math.abs(page-n)<=1).map(n=>`<button data-page="${n}" class="${n===page?'current':''}">${n}</button>`).join('')}<button id="next" ${page===pages?'disabled':''} aria-label="Próxima página">›</button></div></div></section>`}
function reports(){return `<div class="report-cards">${[['clipboard','Solicitações por setor','Consulte os pedidos, quantidades e o andamento de cada setor.','sector'],['check','Materiais entregues','Visualize as solicitações concluídas e exporte o relatório.','done'],['box','Catálogo de materiais','Exporte o catálogo de produtos disponíveis para solicitação.','catalog']].map(([ic,title,desc,id])=>`<article class="panel report-card"><span class="stat-icon purple">${icon(ic)}</span><h2>${title}</h2><p>${desc}</p><button class="btn" data-report="${id}">${icon('download')} Gerar relatório</button></article>`).join('')}</div>`}
function render(){navigation();main.innerHTML=heading()+((route==='dashboard')?`<div class="intro-strip"><span class="date">${icon('calendar')}${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span>${Store.data.demo?'<span class="demo-tag">Dados demonstrativos</span>':''}</div>`:'')+(route==='dashboard'?stats()+charts():'')+(route==='reports'?reports():'')+(route==='products'?`<div class="data-notice"><div><strong>Produtos organizados por ATA</strong><p>Vincule cada produto às ATAs em que está disponível. Cada ATA pode atender vários setores e conter vários produtos.</p></div><button class="subtle-link" id="template-download">${icon('download')} Baixar modelo</button></div>`:'')+((route==='dashboard'||route==='requests')?waitingPanel(getRows()):'')+table();bind()}
function clone(ids){const type=activeType();const clonedGroups=new Map();Store.data[type].filter(r=>ids.includes(r.id)).forEach(r=>{const copy=structuredClone(r);delete copy.id;if(type==='requests'){const oldGroup=r.groupId||r.id;if(!clonedGroups.has(oldGroup))clonedGroups.set(oldGroup,crypto.randomUUID());copy.groupId=clonedGroups.get(oldGroup);copy.requestNumber='SOL-'+new Date().getFullYear()+'-'+copy.groupId.slice(0,8).toUpperCase();copy.received=0;copy.receipts=[];copy.status='Pendente'}if(type==='products')copy.code+='-COPIA-'+Math.random().toString(36).slice(2,5).toUpperCase();if(type==='sectors')copy.name+=' (cópia '+Math.random().toString(36).slice(2,5)+')';if(type==='atas')copy.number+=' (cópia '+Math.random().toString(36).slice(2,5)+')';const added=Store.add(type,copy);if(type==='products'){for(const ata of atasForProduct(Store.data,r.id))ata.productIds.push(added.id);Store.save()}});selected.clear();toast('Registro(s) clonado(s).');render()}
function bind(){const on=(id,event,fn)=>{const el=document.getElementById(id);if(el)el.addEventListener(event,fn)};on('import','click',importModal);on('new','click',()=>activeType()==='requests'?requestEditor(null,render):edit(activeType(),null,render));on('export','click',()=>FileIO.export(activeType(),getRows()));on('export-table','click',()=>FileIO.export(activeType(),getRows()));on('template-download','click',()=>FileIO.template());on('print','click',printReport);on('print-table','click',printReport);on('period','change',e=>{chartPeriod=e.target.value;render()});for(const [id,key] of [['search','search'],['code-filter','code'],['sector-filter','sector'],['status-filter','status'],['ata-filter','ataId']])on(id,id.includes('filter')&&id!=='code-filter'?'change':'input',e=>{const cursor=e.target.selectionStart;filters[key]=e.target.value;page=1;selected.clear();render();const field=document.getElementById(id);field.focus();if(cursor!==null&&field.setSelectionRange)field.setSelectionRange(cursor,cursor)});on('reset-filters','click',()=>{filters={search:'',sector:'',status:'',code:''};page=1;selected.clear();render()});on('prev','click',()=>{page--;render()});on('next','click',()=>{page++;render()});on('page-size','change',e=>{pageSize=Number(e.target.value);page=1;render()});main.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);render()});main.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const row=Store.data[activeType()].find(x=>x.id===b.dataset.edit);activeType()==='requests'?requestEditor(row,render):edit(activeType(),row,render)});main.querySelectorAll('[data-request-details]').forEach(b=>b.onclick=()=>requestSummary(b.dataset.requestDetails,render));main.querySelectorAll('[data-receive]').forEach(b=>b.onclick=()=>requestSummary(b.dataset.receive,render));main.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>confirmDelete(activeType(),[b.dataset.delete],()=>{selected.clear();render()}));main.querySelectorAll('[data-clone]').forEach(b=>b.onclick=()=>clone([b.dataset.clone]));main.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{b.checked?selected.add(b.dataset.select):selected.delete(b.dataset.select);render()});on('select-all','change',e=>{const rows=getRows().slice((page-1)*pageSize,page*pageSize);rows.forEach(r=>e.target.checked?selected.add(r.id):selected.delete(r.id));render()});on('bulk-clone','click',()=>clone([...selected]));on('bulk-delete','click',()=>confirmDelete(activeType(),[...selected],()=>{selected.clear();render()}));on('bulk-status','change',e=>{if(!e.target.value)return;Store.data.requests.forEach(r=>{if(selected.has(r.id)&&remaining(r)>0)r.status='Cancelada'});Store.save();selected.clear();toast('Status atualizados.');render()});let dragKey;main.querySelectorAll('th[data-key]').forEach(th=>{th.onclick=()=>{sort={key:th.dataset.key,direction:sort.key===th.dataset.key?-sort.direction:1};render()};th.ondragstart=e=>{dragKey=th.dataset.key;e.dataTransfer.setData('text/plain',dragKey)};th.ondragover=e=>e.preventDefault();th.ondrop=e=>{e.preventDefault();const source=e.dataTransfer.getData('text/plain')||dragKey;if(!Store.data.columns.includes(source))return;const columns=[...Store.data.columns];columns.splice(columns.indexOf(source),1);columns.splice(columns.indexOf(th.dataset.key),0,source);Store.data.columns=columns;Store.save();render()}});main.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{if(b.dataset.report==='catalog')FileIO.export('products',Store.data.products);else if(b.dataset.report==='done')FileIO.export('requests',Store.data.requests.filter(r=>r.status==='Concluída'));else{filters={search:'',sector:'',status:'',code:''};sort={key:'sector',direction:1};render();document.getElementById('sector-filter').focus();toast('Selecione um setor e clique em Exportar.')}})}
function printReport(){const old=pageSize;pageSize=Math.max(1,getRows().length);page=1;render();window.print();pageSize=old;render()}
function navigate(){const key=location.hash.slice(1);route=routes[key]?key:'dashboard';filters={search:'',sector:'',status:'',code:''};page=1;sort={key:route==='dashboard'||route==='requests'?'date':route==='products'?'code':route==='sectors'?'name':'number',direction:route==='dashboard'?-1:1};selected.clear();render()}
document.body.classList.toggle('dark',Store.data.theme==='dark');document.getElementById('theme').dataset.icon=Store.data.theme==='dark'?'sun':'moon';hydrate();document.getElementById('theme').onclick=()=>{Store.data.theme=Store.data.theme==='dark'?'light':'dark';document.body.classList.toggle('dark',Store.data.theme==='dark');document.getElementById('theme').innerHTML=icon(Store.data.theme==='dark'?'sun':'moon');Store.save()};window.addEventListener('hashchange',navigate);
async function importFiles(files){if(!files.length)return;try{const result=await FileIO.read(files);importPreview(result,()=>{location.hash='products';if(route==='products')render()})}catch(e){toast(e.message);const el=document.getElementById('import-error');if(el)el.textContent=e.message}finally{document.getElementById('file-input').value=''}}document.getElementById('file-input').onchange=e=>importFiles(e.target.files);document.addEventListener('import-files',e=>importFiles(e.detail));document.getElementById('help').onclick=()=>{open('Como usar o Supri',`<div class="modal-body"><p><b>1. Cadastre sua estrutura.</b> Cadastre os setores e a ATA. Na ATA, selecione os setores participantes e os produtos. Você também pode vincular os produtos pelo catálogo ou importar uma planilha para a ATA escolhida.</p><p><b>2. Crie solicitações.</b> Busque por código ou nome e adicione vários produtos. Selecione a ATA e um setor participante. Informe produtos dessa ATA, quantidades, responsável e ramal. O sistema gera um aviso com os materiais aguardados.</p><p><b>Recebimentos e baixa.</b> Clique no ✓ da solicitação ou em Ver solicitação / dar baixa no aviso do setor. Registre somente o que chegou agora: entregas parciais mantêm o saldo em aberto; o recebimento total conclui o item automaticamente.</p><p><b>3. Organize e acompanhe.</b> Combine os filtros, ordene clicando nos títulos e arraste as colunas das solicitações.</p><p><b>4. Exporte e imprima.</b> O relatório respeita os filtros. A exportação inclui as abas de origem importadas, preservando as propriedades de formatação compatíveis com a biblioteca.</p><p class="hint">Os dados ficam apenas neste navegador. Exporte periodicamente. Arquivos muito grandes podem exceder a capacidade do armazenamento local. Esta aplicação front-end não sincroniza dados entre computadores.</p><p>${Store.data.demo?'Os registros iniciais são demonstrativos. Você pode removê-los para começar.':'Seus dados estão ativos neste navegador.'}</p>${Store.data.demo?'<button class="btn danger" id="clear-demo">Remover dados demonstrativos</button>':''}</div>`);const clearButton=document.getElementById('clear-demo');if(clearButton)clearButton.onclick=()=>{open('Começar com uma base vazia',`<div class="modal-body"><p>Todos os cadastros, solicitações e arquivos importados deste navegador serão apagados. Exporte seus dados antes de continuar.</p></div>`,`<div class="modal-footer"><button class="btn" data-close>Cancelar</button><button class="btn danger" id="clear-confirm">Apagar dados e começar</button></div>`);document.getElementById('clear-confirm').onclick=()=>{for(const k of ['products','requests','sectors','atas','sources'])Store.data[k]=[];Store.data.demo=false;Store.save();close();selected.clear();render();toast('Base limpa. Cadastre os setores e importe seus produtos.')}}};navigate();
